update pages set contenu = '{"gabarit":"fiche","chapeau":"JTEKT conçoit et fabrique des composants techniques : systèmes de direction, roulements pour l''industrie et pour l''automobile. En 2025, le groupe a fait appel à Migen pour sécuriser la maintenance de ses installations industrielles.","fiche":[],"contexte":"**Un équipement critique qui tombe sans prévenir immobilise une chaîne entière.** Dans une branche en réorganisation, ces arrêts se paient deux fois : en production perdue et en compétitivité du site.\nLes objectifs posés par JTEKT :\n**Disponibilité maximale des équipements critiques** sur les sites de production.\n**Réduction des temps d''arrêt**, planifiés comme subis.\n**Optimisation de la performance des installations**, au-delà du simple dépannage.\n**Renforcement des équipes internes**, sans réorganiser le service maintenance.","intervention":"**Des techniciens dans l''équipe, pas à côté** : Les techniciens Migen sont intégrés aux équipes de maintenance de JTEKT et présents chaque jour.\n**Surveillance proactive des équipements** : Le dispositif ne se déclenche pas à la panne. Les machines sont suivies pour repérer la dérive avant l''arrêt.\n**Réaction immédiate sur incident** : La présence sur site évite d''attendre la disponibilité d''un intervenant extérieur.\n**Appui aux équipes internes** : Les techniciens accompagnent les équipes JTEKT dans la gestion courante des opérations.\nLe périmètre technique couvre les systèmes automatisés, les lignes de production, les convoyeurs et les autres équipements complexes du parc. Les interventions portent sur la surveillance, la maintenance curative et la gestion des interventions.","resultats":[]}'::jsonb where path = '/preuves/jtekt/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"JTEKT"},{"libelle":"Activité","valeur":"Systèmes de direction, roulements industrie et automobile"},{"libelle":"Secteur","valeur":"Industrie automobile"},{"libelle":"Année","valeur":"2025"},{"libelle":"Périmètre","valeur":"Équipements critiques des sites de production"},{"libelle":"Équipements","valeur":"Systèmes automatisés, lignes de production, convoyeurs"},{"libelle":"Nature des travaux","valeur":"Surveillance, maintenance curative, gestion des interventions"},{"libelle":"Organisation","valeur":"Techniciens intégrés aux équipes de maintenance"}]'::jsonb) where path = '/preuves/jtekt/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"La fiabilité du parc machine progresse","libelle":"Des techniciens spécialisés et une surveillance continue y contribuent directement."},{"valeur":"Les équipes internes gagnent en efficacité","libelle":"Elles sont appuyées au quotidien plutôt que dépassées."},{"valeur":"Les risques d''arrêt reculent","libelle":"Dans un contexte industriel où chaque heure de production compte."}]'::jsonb) where path = '/preuves/jtekt/';
